        if (v === 'low') ui.prefs.volume = 0.3;
        else if (v === 'mid') ui.prefs.volume = 0.6;
        else if (v === 'high') ui.prefs.volume = 1;
        saveAudioPrefs(ui.prefs);
        ports.audio?.apply(ui.prefs);
        break;
      }
    }
