export class TowerManager {
  private towers: Tower[] = [];
  private group: Group;
  private map: GameMap;
  private distanceField: DistanceField;

  constructor(group: Group, map: GameMap, distanceField: DistanceField) {
    this.group = group;
    this.map = map;
    this.distanceField = distanceField;
  }

  getDistanceField(): DistanceField {
    return this.distanceField;
  }

  canPlace(gridPos: GridPosition): boolean {
    const cell = this.map.getCellAt(gridPos.row, gridPos.col);
    return !!cell && cell.cellType === CellType.Buildable && !cell.occupied;
  }

  place(config: TowerConfig, gridPos: GridPosition): Tower | null {
    if (!this.canPlace(gridPos)) return null;

    const cell = this.map.getCellAt(gridPos.row, gridPos.col)!;
    const worldPos = this.map.getWorldPosition(gridPos);
    const tower = new Tower(config, gridPos, worldPos.x, worldPos.z);
    cell.occupied = true;
    this.towers.push(tower);

    this.group.add(tower.getObject3D());
    tower.startPlacementAnimation();
    return tower;
  }

  remove(tower: Tower): void {
    const cell = this.map.getCellAt(tower.gridPos.row, tower.gridPos.col);
    if (cell) cell.occupied = false;
    this.group.remove(tower.getObject3D());
    tower.dispose();
    const idx = this.towers.indexOf(tower);
    if (idx !== -1) this.towers.splice(idx, 1);

  }

  getTowerAt(gridPos: GridPosition): Tower | undefined {
    return this.towers.find(
      (t) => t.gridPos.row === gridPos.row && t.gridPos.col === gridPos.col,
    );
  }

  upgradeTower(tower: Tower, newConfig: TowerConfig): void {
    tower.upgrade(newConfig);
  }

  getTowers(): readonly Tower[] {
    return this.towers;
  }

  update(delta: number): void {
    for (const tower of this.towers) {
      tower.update(delta);
    }
  }

  dispose(): void {
    for (const tower of this.towers) {
      this.group.remove(tower.getObject3D());
      tower.dispose();
    }
    this.towers = [];
  }
}

export function generateBudgetWave(
  budget: number,
  level: number,
  availableTypes: EnemyConfig[],
  rand: () => number,
): WaveConfig {
  const hpScale = calcHPScale(level);
  const entries: WaveConfig["entries"] = [];
  let remaining = budget;

  // Shuffle available types for variety
  const shuffled = [...availableTypes];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  for (const baseConfig of shuffled) {
    if (remaining <= 0) break;

    const category = classifyEnemy(baseConfig);
    const cost = ENEMY_BUDGET_COST[category] ?? 5;
    const maxCount = Math.floor(remaining / cost);
    if (maxCount <= 0) continue;

    // Random count between 1 and maxCount (biased toward fewer for expensive types)
    const count =
      cost >= 30
        ? Math.min(maxCount, 1 + Math.floor(rand() * 2))
        : Math.min(maxCount, 2 + Math.floor(rand() * (maxCount - 1)));

    if (count <= 0) continue;

    entries.push({
      count,
      spawnInterval: Math.max(0.3, 1.2 - level * 0.05),
      enemyConfig: {
        ...baseConfig,
        hp: Math.round(baseConfig.hp * hpScale),
        speed: baseConfig.speed + level * 0.05,
        reward: Math.max(
          1,
          Math.round(baseConfig.reward * calcRewardScale(level)),
        ),
      },
    });

    remaining -= count * cost;
  }

  // If budget remains and we have entries, pad with basic enemies
  if (remaining > 5 && entries.length > 0) {
    const basicCost = ENEMY_BUDGET_COST["basic"];
    const padCount = Math.floor(remaining / basicCost);
    if (padCount > 0) {
      entries.push({
        count: padCount,
        spawnInterval: 0.8,
        enemyConfig: {
          ...BASIC_ENEMY,
          hp: Math.round(BASIC_ENEMY.hp * hpScale),
          speed: BASIC_ENEMY.speed + level * 0.05,
          reward: Math.max(
            1,
            Math.round(BASIC_ENEMY.reward * calcRewardScale(level)),
          ),
        },
      });
    }
  }

  return { entries };
}

