export function beginWave(w: World): void {
  const s = w.wave;

  if (s.phase === 'spawning') {
    w.events.push({ type: 'waveRejected', reason: 'spawning' });
    return;
  }
  if (s.phase === 'done') {
    w.events.push({ type: 'waveRejected', reason: 'done' });
    return;
