    const r = ENEMIES[c.defId].radius;
    if (segmentDistanceSq(c.x, c.y, fromX, fromY, p.x, p.y) > r * r) continue;

    p.hits.push(c.id);
    hit(w, c, p.damage, s, source);

    if (p.pierce <= 0) {
      p.dead = true;
      break;
    }
    p.pierce--;
  }
